From 656a84a3deb9c7aff5f9187346e7354b8a03e43e Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 12:51:08 +0100
Subject: [PATCH] libtaskmanager: limit how often Wayland window icons are
 re-read

A window that changes its icon very often made plasmashell open a pipe
for each change, until it ran out of file descriptors and died. Now one
icon is read at a time, at most every 100 ms, without dropping app data.

BUG: 487390
---
 libtaskmanager/waylandtasksmodel.cpp | 37 ++++++++++++++++++----------
 1 file changed, 24 insertions(+), 13 deletions(-)

diff --git a/libtaskmanager/waylandtasksmodel.cpp b/libtaskmanager/waylandtasksmodel.cpp
index ed0b90cbbf..37bf915295 100644
--- a/libtaskmanager/waylandtasksmodel.cpp
+++ b/libtaskmanager/waylandtasksmodel.cpp
@@ -71,6 +71,8 @@ public:
     QPointer<PlasmaWindow> parentWindow;
     bool wasUnmapped = false;
     bool wasMapped = false;
+    bool iconRequested = false;
+    bool iconChangedWhileRequested = false;

 Q_SIGNALS:
     void mapped();
@@ -129,6 +131,19 @@ protected:
         Q_EMIT appIdChanged();
     }
     void org_kde_plasma_window_icon_changed() override
+    {
+        if (iconRequested) {
+            iconChangedWhileRequested = true;
+            return;
+        }
+        requestIcon();
+    }
+    void org_kde_plasma_window_themed_icon_name_changed(const QString &name) override
+    {
+        icon = QIcon::fromTheme(name);
+        Q_EMIT iconChanged();
+    }
+    void requestIcon()
     {
         int pipeFds[2];
         if (pipe2(pipeFds, O_CLOEXEC) != 0) {
@@ -175,14 +190,18 @@ protected:
         connect(watcher, &QFutureWatcher<QIcon>::finished, this, [this, watcher] {
             icon = watcher->future().result();
             Q_EMIT iconChanged();
+            // Some windows change their icon very often, don't update it more than a few times per second.
+            QTimer::singleShot(100ms, this, [this] {
+                iconRequested = false;
+                if (iconChangedWhileRequested) {
+                    iconChangedWhileRequested = false;
+                    requestIcon();
+                }
+            });
         });
         connect(watcher, &QFutureWatcher<QIcon>::finished, watcher, &QObject::deleteLater);
         watcher->setFuture(future);
-    }
-    void org_kde_plasma_window_themed_icon_name_changed(const QString &name) override
-    {
-        icon = QIcon::fromTheme(name);
-        Q_EMIT iconChanged();
+        iconRequested = true;
     }
     void org_kde_plasma_window_state_changed(uint32_t flags) override
     {
@@ -596,12 +615,6 @@ void WaylandTasksModel::Private::addWindow(PlasmaWindow *window)
     });

     QObject::connect(window, &PlasmaWindow::iconChanged, q, [window, this] {
-        // The icon in the AppData struct might come from PlasmaWindow if it wasn't
-        // filled in by windowUrlFromMetadata+appDataFromUrl.
-        // TODO: Don't evict the cache unnecessarily if this isn't the case. As icons
-        // are currently very static on Wayland, this eviction is unlikely to happen
-        // frequently as of now.
-        appDataCache.remove(window);
         this->dataChanged(window, Qt::DecorationRole);
     });

@@ -831,8 +844,6 @@ QIcon WaylandTasksModel::Private::icon(PlasmaWindow *window)
         return app.icon;
     }

-    appDataCache[window].icon = window->icon;
-
     return window->icon;
 }

